import { test, expect } from '@playwright/test';

/** A role credential from the environment; fails clearly when it is not set. */
function credential(name: string, value: string | undefined): string {
  if (!value) throw new Error(`Environment variable ${name} is not set`);
  return value;
}

test('SCN-0004: Prevent login for a locked-out user', async ({ page }) => {
  // Expected (REQ-001): Locked-out user: login is prevented and the message Epic sadface: Sorry, this user has been locked out. is shown.
  await page.goto('/');
  await page.getByRole('textbox', { name: 'Username', exact: true }).fill(credential('SAUCEDEMO_LOCKED_OUT_USERNAME', process.env.SAUCEDEMO_LOCKED_OUT_USERNAME));
  await page.getByRole('textbox', { name: 'Password', exact: true }).fill(credential('SAUCEDEMO_LOCKED_OUT_PASSWORD', process.env.SAUCEDEMO_LOCKED_OUT_PASSWORD));
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await expect(page.getByText('Epic sadface: Sorry, this user has been locked out.', { exact: true })).toBeVisible();
});
